const root=document.querySelector('.voyage'),preparation=document.querySelector('.preparation'),sceneUI=document.querySelector('.scene-ui'),subLabel=document.querySelector('.sub-label'),slider=document.querySelector('#depth-control'),stops=[...document.querySelectorAll('.stop')];
const zones=[['浅海','海面光线还在身边。让眼睛慢慢适应海洋的蓝。'],['暮光带','阳光渐渐淡去，水母在幽蓝中轻轻漂浮。'],['午夜带','光线消失的地方，岩壁与生命的轮廓缓缓浮现。'],['深渊带','经过温暖的烟囱微光，向安静的海床靠近。']];
function showDepth(value){const depth=Math.max(0,Math.min(6000,Number(value)||0)),zone=depth<200?0:depth<1000?1:depth<3000?2:3;root.dataset.zone=zone;slider.value=depth;document.querySelector('#depth').innerHTML=depth.toLocaleString('zh-CN')+' <small>m</small>';document.querySelector('#zone-description').textContent=zones[zone][1];stops.forEach((stop,i)=>{stop.classList.toggle('active',i===zone);stop.setAttribute('aria-pressed',String(i===zone));});document.title='微光深处 · '+(root.dataset.mode==='ready'?'潜航准备':zones[zone][0]);}
function enter(depth=0,focus=false){root.dataset.mode='scene';document.querySelector('.connection').innerHTML='<i></i>微光号 · 海域观景';preparation.hidden=true;subLabel.hidden=true;sceneUI.hidden=false;showDepth(depth);document.querySelector('#announcement').textContent='已进入海洋场景，可以使用深度刻度查看沿途风景。';if(focus)slider.focus();}
document.querySelector('#launch').addEventListener('click',()=>enter(0,true));stops.forEach(stop=>stop.addEventListener('click',()=>enter(stop.dataset.depth)));slider.addEventListener('input',()=>showDepth(slider.value));document.querySelector('#return').addEventListener('click',()=>{root.dataset.mode='ready';document.querySelector('.connection').innerHTML='<i></i>微光号 · 准备出发';preparation.hidden=false;subLabel.hidden=false;sceneUI.hidden=true;showDepth(0);document.querySelector('#launch').focus();});document.querySelector('#pause').addEventListener('click',event=>{const paused=root.classList.toggle('paused');event.currentTarget.textContent=paused?'继续漂浮':'暂停漂浮';event.currentTarget.setAttribute('aria-pressed',String(paused));});showDepth(0);

